            definitions[677] = ManifestRetained("Hero_Vesper", "h.vesper.ring.vessel", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("夢輪の器", "Dream Ring Vessel"), MaxRank = 3, RankCost = 1, Mechanism = ManifestPair("Hero_Vesper", "h.vesper.ring.vessel", "St_R_SanctuaryOfEl", "St_M_Charge", MemoryEventKind.ConfirmedUse, new int[] { 3000, 4000, 5000 }) }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), new MemoryOwnership { TargetMemory = "St_M_Charge", SourceMemories = new string[] { "St_R_SanctuaryOfEl" } }, "docs/specs/v1.31-clusters-vesper.md", Array.Empty<string>(), "旧効果を置換: Bの旧中心表③④へ移行。聖域use→直接Recv(聖域;use,30/40/50)、3段で30/40/50%。印とタックルhit条件を撤去。聖域と重装タックルの両方を装備する条件は維持。両Identityで有効。旧3段を保持。");
            definitions[678] = ManifestRetained("Hero_Vesper", "h.vesper.ring.armor", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("夢輪の鎧", "Dream Ring Armor"), MaxRank = 3, RankCost = 1, Mechanism = ManifestPair("Hero_Vesper", "h.vesper.ring.armor", "St_D_MercyOfEl", "St_M_Charge", MemoryEventKind.CriticalHit, new int[] { 3000, 4000, 5000 }) }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), new MemoryOwnership { TargetMemory = "St_M_Charge", SourceMemories = new string[] { "St_D_MercyOfEl" } }, "docs/specs/v1.31-clusters-vesper.md", Array.Empty<string>(), "旧効果を置換: Bの旧中心表③④へ移行。慈悲crit→直接Recv(慈悲;crit,30/40/50)、3段で30/40/50%。タックル由来の印を撤去。慈悲と重装タックルの両方を装備する条件は維持（慈悲専用ペアなので決意と同時要求しない）。旧3段を保持。");
            definitions[679] = ManifestRetained("Hero_Vesper", "h.vesper.ring.renewal", new ClusterStarDef { Kind = ClusterStarKind.Choice, Name = new Txt("夢輪の再生", "Dream Ring Renewal"), MaxRank = 5, RankCost = 1, Options = new ClusterStarDef[] { new ClusterStarDef { Kind = ClusterStarKind.GimmickBoost, Name = new Txt("満ちる誓言", "Filling Vows"), MaxRank = 5, RankCost = 1, Memory = "St_D_Resolve", ScopedModifier = new ScopedModifierDef { ScopeKind = ScopeKind.Memory, ScopeMemory = "St_D_Resolve", TargetEffectIds = Array.Empty<string>(), TargetEffects = Array.Empty<GimmickEffect>(), Amount = ModifierUnits.FromPercent(1m) } }, new ClusterStarDef { Kind = ClusterStarKind.GimmickBoost, Name = new Txt("灯る慈悲", "Kindling Mercy"), MaxRank = 5, RankCost = 1, Memory = "St_D_MercyOfEl", ScopedModifier = new ScopedModifierDef { ScopeKind = ScopeKind.EffectChannel, ScopeMemory = "St_D_MercyOfEl", TargetEffectIds = new string[] { "h.vesper.deep.body", "h.vesper.route.mercy.2", "h.vesper.route.mercy.4", "h.vesper.route.mercy.7", "h.vesper.wall", "vesper.bridge.recall.n1", "vesper.bridge.recall.n2", "vesper.bridge.recall.x", "vesper.mem.mercy.c1.n1", "vesper.mem.mercy.c1.n2", "vesper.mem.mercy.c2.n1", "vesper.mem.mercy.c2.n2", "vesper.mem.mercy.c3.n1", "vesper.mem.mercy.c3.n2", "vesper.mem.mercy.c4.n1", "vesper.mem.mercy.c4.n2", "vesper.outer.shared-light.n1", "vesper.outer.shared-light.n2" }, TargetEffects = Array.Empty<GimmickEffect>(), Amount = ModifierUnits.FromPercent(1m) } } } }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-vesper.md", Array.Empty<string>(), "旧効果を置換: Choice：B(resolve,1) / B(mercy,1) / 5段。外側の橋の位置・IDを維持");
            definitions[680] = ManifestRetained("Hero_Vesper", "h.vesper.key", new ClusterStarDef { Kind = ClusterStarKind.Keystone, Name = new Txt("審問の構え", "Inquisitor's Stance"), MaxRank = 1, RankCost = 1, KeystoneDefinition = ManifestKeystone("Hero_Vesper", "h.vesper.key", Array.Empty<string>(), Array.Empty<AuthoredKeystoneSpec>(), new AuthoredKeystoneSpec[] { new AuthoredKeystoneSpec { Layer = KeystoneLayer.NativeDamage, Scope = new KeystoneScope(sourceKind: KeystoneSourceKind.NativeMemory, sourceSelectors: new[] { MemorySelector.Parse("@Q|@R") }), Field = KeystoneField.Value, Percent = -10m } }, prerequisites: Array.Empty<string>(), cost: Content.KeystoneCost) }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-vesper.md", new string[] { "C07" }, "既存刻印に代償を追加（ID・既存Powerは維持、強化なし）。利点: 既存 Power.Retaliation=25（被弾後3秒、攻撃力・魔力+25%、重ならず更新）を維持／代償: 装備Q/Rの直接ダメージ-10%。M4の記憶限定負倍率（C07）。被弾を強制せず決意/慈悲の両方を維持。");
